import{z as t,x as n,o as r,c as l,q as E,j as p,D as e,d as i,s as c,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"kdump 与 crash","description":"","frontmatter":{"title":"kdump 与 crash","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kdump-crash.md","filePath":"cs/kdump-crash.md","lastUpdated":1791413859000}'),A={name:"cs/kdump-crash.md"};function B(d,a,m,h,u,k){const s=n("Mermaid");return r(),l("div",null,[a[2]||(a[2]=E('<h1 id="kdump-与-crash" tabindex="-1">kdump 与 crash <a class="header-anchor" href="#kdump-与-crash" aria-label="Permalink to &quot;kdump 与 crash&quot;">​</a></h1><div class="epigraph"><p>kdump 用 kexec 进第二内核，把崩溃瞬间的内存当 ram 盘转出；crash 工具在事后解析 vmcore。</p><footer>—— 据 Linux kdump 文档；kexec；[printk](/cs/printk-logging) 环可能不够事后分析</footer></div><p><a href="/cs/ebpf-observability">eBPF</a> 看活体。机器已经 oops。缺口是 <strong>保留内存 + 第二内核</strong> 抓 dump。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃时锁可能死、文件系统可能不可信。kexec 跳到预留的 capture kernel，旧内存只读。缺口：预留大小；加密盘；与 watchdog 的配合。本课不把 crash 命令当教程全文。</p><p><span class="marginnote">pstore/ramoops 是更小的紧急日志。对象是整机内存镜像，不是 coredump 用户进程——那是另一条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动预留 crashkernel → panic 时 kexec → 写 vmcore。对照 <a href="/cs/suspend-resume">hibernate</a>：一个有意写镜像，一个意外。对照 <a href="/cs/fsck">fsck</a>：dump 后再修盘。对照 makedumpfile 过滤页。</p><p><span class="marginnote">直觉类比：crashkernel 预留区像救生艇——平时占着甲板空间没人用；船一进水（panic），你不可能现场造船，只能跳上早已挂好的那艘。「不能崩溃后再装」说的就是这个。</span></p>',9)),(r(),p(o,null,{default:e(()=>[c(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAN%5B%22panic%22%5D%20--%3E%20KX%5B%22kexec%20%E6%8D%95%E8%8E%B7%E5%86%85%E6%A0%B8%22%5D%0A%20%20KX%20--%3E%20VM%5B%22%E5%86%99%20vmcore%22%5D%0A%20%20VM%20--%3E%20CR%5B%22crash%20%E8%A7%A3%E6%9E%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>kdump 把「死内核的 RAM」变成可分析文件，是生产根因的最后手段。它需要事先预留，不能崩溃后再装。不要写成云监控套餐。与 <a href="/cs/kpti-os">KPTI</a>：解析要懂页表。</p><p>失败：预留不够、设备驱动在第二内核缺失。</p><p>实现上：crashkernel= 预留必须在启动时做，崩溃后再留来不及。第二内核驱动要能写盘或网，常用精简 config。过滤掉缓存页可缩小 dump。 读法上只引用<a href="/cs/ebpf-observability">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">数字实例：一台 256 GB 内存的机器，通常只用启动参数预留几百 MB（如 crashkernel=512M）给第二内核；事后用 makedumpfile 过滤掉缓存页，几百 GB 的内存现场常能压成几 GB 的 vmcore 文件。</span></p>',5)),(r(),p(o,null,{default:e(()=>[c(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%90%AF%E5%8A%A8%E6%97%B6%EF%BC%9A%E5%88%92%E5%87%BA%20crashkernel%20%E9%A2%84%E7%95%99%E5%8C%BA%EF%BC%8C%E5%B9%B3%E6%97%B6%E9%97%B2%E7%BD%AE%22%5D%20--%3E%20C%5B%22%E8%BF%90%E8%A1%8C%E6%9C%9F%EF%BC%9A%E6%AD%A3%E5%B8%B8%E5%86%85%E6%A0%B8%E7%94%A8%E5%85%B6%E4%BD%99%E5%86%85%E5%AD%98%22%5D%0A%20%20C%20--%3E%20P%5B%22%E6%9F%90%E5%A4%A9%20panic%EF%BC%9A%E5%8E%9F%E5%86%85%E6%A0%B8%E5%B7%B2%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20P%20--%3E%20K%5B%22kexec%20%E6%8A%8A%20capture%20kernel%20%E8%A3%85%E8%BF%9B%E9%A2%84%E7%95%99%E5%8C%BA%E5%B9%B6%E8%B7%B3%E8%BF%87%E5%8E%BB%22%5D%0A%20%20K%20--%3E%20R%5B%22%E6%97%A7%E5%86%85%E6%A0%B8%E5%86%85%E5%AD%98%E5%8E%9F%E5%B0%81%E4%B8%8D%E5%8A%A8%EF%BC%8C%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20R%20--%3E%20W%5B%22capture%20kernel%20%E6%8A%8A%E5%AE%83%E8%BD%AC%E6%88%90%20vmcore%22%5D%0A%20%20W%20--%3E%20A%5B%22%E4%BA%8B%E5%90%8E%E7%94%A8%20crash%20%E5%88%86%E6%9E%90%E6%A0%B9%E5%9B%A0%22%5D%0A%20%20B%20--%3E%7C%22%E6%B2%A1%E9%A2%84%E7%95%99%22%7C%20X%5B%22%E5%B4%A9%E6%BA%83%E5%90%8E%E6%97%A0%E5%B9%B2%E5%87%80%E5%86%85%E5%AD%98%E6%94%BE%E7%AC%AC%E4%BA%8C%E5%86%85%E6%A0%B8%EF%BC%8Cdump%20%E7%9B%B4%E6%8E%A5%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>kdump 与 crash</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有过滤策略。不保证虚拟机的 pvpanic 路径。下一课崩溃语义：oops 与 panic。</p><p>版本字段会变，课序钉的是机制对象「kdump 与 crash」，不是某一主线内核的结构体名。 后课默认：可 kexec 出 vmcore。oops 与 panic 如何决定活还是死，下一课。</p><p><span class="marginnote">常见误区：把 kdump 当成「出了事装个工具就能抓」。实际上它依赖崩溃前就位的三件事——启动参数预留、第二内核的精简 initramfs、能写盘或传网的驱动；缺一件，现场就只剩重启一条路。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>kdump：预留内核 + kexec + vmcore。</li><li>分析用 crash；依赖事先配置。</li><li>oops/panic 是下一课。</li><li>出处：kdump；kexec；crash 工具。</li></ul>',8))])}const C=t(A,[["render",B]]);export{f as __pageData,C as default};
